{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol-rich palm oil, a structurally related amphipathic isoprenoid with a polar head and long unsaturated prenyl tail, is reported to have poor oral bioavailability in humans, supporting low bioavailability for the query ubiquinone/polyprenyl structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Human lycopene studies consistently show very low systemic availability (e.g., 0.17% from tomato paste), indicating that highly lipophilic long-chain isoprenoid/carotenoid molecules are poorly absorbed; this transfers moderately to the query's long polyprenyl chain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Only about 1.2% of a synthetic lycopene dose appeared in blood after oral administration, reinforcing the poor oral bioavailability of large lipophilic isoprenoid-type molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene showed high human bioavailability (58.5%), but this is a nonpolar carotenoid hydrocarbon without the polar quinone head of the query, so it is only weakly transferable and does not outweigh the low-bioavailability evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is coenzyme Q10/ubiquinone-10, a highly lipophilic polyprenyl benzoquinone. Structurally related tocotrienols show poor oral bioavailability, and lycopene-type long isoprenoids generally show low systemic availability. The high phytoene values are less transferable because phytoene lacks the polar quinone head. Overall, F is better supported as below 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for coenzyme Q10/ubiquinone-10 is provided in the evidence set.",
    "The effect of formulation (e.g., solubilized vs. crystalline) on the query's bioavailability is not addressed by the supplied records.",
    "Human data for tocotrienols are qualitative ('poor') rather than a numeric F value, limiting precise threshold comparison."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tocotrienol"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C07", "C04", "C22"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "lycopene"
    },
    {
      "applicability": "low",
      "card_ids": ["C02", "C14"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "phytoene"
    }
  ],
  "revision_action": "initial"
}

